import java.io.*;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import com.android.apksig.ApkSigner;
public class SignApk{public static void main(String[] args)throws Exception{KeyStore store=KeyStore.getInstance("PKCS12");try(InputStream in=new FileInputStream(args[0])){store.load(in,"android".toCharArray());}PrivateKey key=(PrivateKey)store.getKey("learning-debug","android".toCharArray());X509Certificate certificate=(X509Certificate)store.getCertificate("learning-debug");ApkSigner.SignerConfig config=new ApkSigner.SignerConfig.Builder("learning-debug",key,Collections.singletonList(certificate)).build();new ApkSigner.Builder(Collections.singletonList(config)).setInputApk(new File(args[1])).setOutputApk(new File(args[2])).setMinSdkVersion(26).setV1SigningEnabled(true).setV2SigningEnabled(true).setV3SigningEnabled(true).build().sign();}}
